"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

// Table Row: generated by UIX from the design system. Same variants and sizes as the Figma component.

const tableVariants = cva(
  "w-full overflow-x-auto bg-surface border border-line-default rounded-lg",
);

export interface TableProps
  extends React.TableHTMLAttributes<HTMLTableElement>,
    VariantProps<typeof tableVariants> {
  /** Classes for the scrolling frame around the table. */
  frameClassName?: string;
}

const Table = React.forwardRef<HTMLTableElement, TableProps>(
  ({ className, frameClassName, ...props }, ref) => (
    <div data-slot="table" data-kind="surface" className={cn(tableVariants({  }), frameClassName)}>
      <table ref={ref} className={cn("w-full border-collapse text-left", className)} {...props} />
    </div>
  ),
);
Table.displayName = "Table";

const TableHeader = React.forwardRef<HTMLTableSectionElement, React.HTMLAttributes<HTMLTableSectionElement>>(({ className, ...props }, ref) => (
  <thead ref={ref} className={cn("", className)} {...props} />
));
TableHeader.displayName = "TableHeader";

const TableBody = React.forwardRef<HTMLTableSectionElement, React.HTMLAttributes<HTMLTableSectionElement>>(({ className, ...props }, ref) => (
  <tbody ref={ref} className={cn("[&_tr:last-child]:border-0", className)} {...props} />
));
TableBody.displayName = "TableBody";

const TableRow = React.forwardRef<HTMLTableRowElement, React.HTMLAttributes<HTMLTableRowElement>>(({ className, ...props }, ref) => (
  <tr ref={ref} className={cn("border-b transition-colors border-line-subtle hover:bg-subtle aria-selected:bg-brand-subtle aria-selected:hover:bg-brand-subtle", className)} {...props} />
));
TableRow.displayName = "TableRow";

const TableHead = React.forwardRef<HTMLTableCellElement, React.HTMLAttributes<HTMLTableCellElement>>(({ className, ...props }, ref) => (
  <th ref={ref} className={cn("h-[44px] px-3 text-left align-middle bg-subtle text-label-small text-fg-secondary", className)} {...props} />
));
TableHead.displayName = "TableHead";

const TableCell = React.forwardRef<HTMLTableCellElement, React.HTMLAttributes<HTMLTableCellElement>>(({ className, ...props }, ref) => (
  <td ref={ref} className={cn("h-16 px-3 align-middle text-body-small text-fg-secondary", className)} {...props} />
));
TableCell.displayName = "TableCell";

export { Table, TableHeader, TableBody, TableRow, TableHead, TableCell, tableVariants };
